    let sorted = sort3(abs(hit));
    let edge = 1.0 - smoothstep(0.0, 0.026, sorted.x);
    color = mix(color, mix(vec3f(1.0), spectrum * 0.30 + 0.70, 0.5), edge * 0.7);
    let cell = floor(hit.xy * 180.0);
